"""The append-only event log. One file per case, one JSON object per line.

JSONL rather than a JSON array on purpose: an append is a single write with no
read-modify-write, so Devin, the CALL-E webhook and the API can all append
concurrently without corrupting the file, and `tail -f` works while debugging.

`seq` is monotonic within a case, which is what lets the UI poll with `?since=`
and get exactly the events it has not seen -- the same read path a replay uses,
so the offline demo is not a separate code path that can rot.
"""

from __future__ import annotations

import json
import os
import threading
from datetime import datetime, timezone
from pathlib import Path

from packages.contracts.enums import Actor, Level, Stage
from packages.contracts.models import Event

_LOCKS: dict[Path, threading.Lock] = {}
_LOCKS_GUARD = threading.Lock()


def _lock_for(path: Path) -> threading.Lock:
    with _LOCKS_GUARD:
        return _LOCKS.setdefault(path, threading.Lock())


def read_events(events_path: Path, since: int = 0) -> list[Event]:
    """Every event after `since`. A malformed line is skipped, never fatal.

    The log is the debugging surface; a half-written line from a crashed writer
    must not take down the endpoint that would show you what crashed.
    """
    if not events_path.exists():
        return []

    events: list[Event] = []
    with events_path.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                event = Event(**json.loads(line))
            except (json.JSONDecodeError, ValueError, TypeError):
                continue
            if event.seq > since:
                events.append(event)
    return events


def last_seq(events_path: Path) -> int:
    events = read_events(events_path)
    return events[-1].seq if events else 0


def append_event(
    events_path: Path,
    *,
    case_id: str,
    actor: Actor,
    stage: Stage,
    message: str,
    level: Level = Level.INFO,
    payload: dict | None = None,
) -> Event:
    """Append one event and return it with its assigned `seq`."""
    events_path.parent.mkdir(parents=True, exist_ok=True)
    with _lock_for(events_path):
        event = Event(
            seq=last_seq(events_path) + 1,
            case_id=case_id,
            ts=datetime.now(timezone.utc),
            actor=actor,
            stage=stage,
            level=level,
            message=message,
            payload=payload or {},
        )
        with events_path.open("a", encoding="utf-8") as fh:
            fh.write(event.model_dump_json() + "\n")
            fh.flush()
            os.fsync(fh.fileno())
    return event
"""Export the frozen contract to its three consumers.

    python -m packages.contracts.export

Writes:
  packages/contracts/schema.json      every model as JSON Schema
  ui/lib/contracts.ts                 TypeScript types, from the same models
  ui/lib/fixtures/*.json              a recorded case, so the cockpit runs with no backend

The point of doing all three from one place: `Claim` is simultaneously our Python
type, CALL-E's `recipient_result_schema` and the cockpit's TypeScript interface.
Generating them together means contract drift is not something anyone has to
remember to avoid -- it is structurally impossible.
"""

from __future__ import annotations

import json
from datetime import date, datetime
from decimal import Decimal
from enum import Enum
from pathlib import Path
from types import UnionType
from typing import Any, Union, get_args, get_origin

from pydantic import BaseModel

from packages.contracts import enums as contract_enums
from packages.contracts import models as contract_models
from packages.contracts.models import Contract

REPO_ROOT = Path(__file__).resolve().parents[2]
SCHEMA_DIR = Path(__file__).resolve().parent
UI_LIB = REPO_ROOT / "ui" / "lib"

MODELS: dict[str, type[BaseModel]] = {
    name: obj
    for name, obj in vars(contract_models).items()
    if isinstance(obj, type)
    and issubclass(obj, BaseModel)
    and obj is not BaseModel
    and obj is not Contract
    and obj.__module__ == contract_models.__name__
}
# Enums live in two places now: Slice B's in enums.py, Slice C's (Channel,
# Currency) alongside Quote in models.py. Scan both so the generated TypeScript
# covers the whole contract.
ENUMS: dict[str, type[Enum]] = {
    name: obj
    for module in (contract_enums, contract_models)
    for name, obj in vars(module).items()
    if isinstance(obj, type)
    and issubclass(obj, Enum)
    and obj.__module__ == module.__name__
}


# ---------------------------------------------------------------------------
# TypeScript generation
# ---------------------------------------------------------------------------


def ts_type(annotation: Any) -> str:
    """Map a Python annotation to TypeScript.

    Money and dates deliberately become `string`: a Decimal serialized as a
    float in JSON is exactly the drift the money rule exists to prevent, so the
    wire format is a string and the UI formats it rather than doing arithmetic.
    """
    if annotation is Any:
        return "unknown"
    if annotation is type(None):
        return "null"
    # `Money` is Annotated[Decimal, ...]; unwrap to the type it decorates.
    if hasattr(annotation, "__metadata__"):
        return ts_type(annotation.__origin__)

    origin = get_origin(annotation)
    if origin in (Union, UnionType):
        parts = [ts_type(a) for a in get_args(annotation)]
        seen: list[str] = []
        for part in parts:
            if part not in seen:
                seen.append(part)
        return " | ".join(seen)
    if origin in (list, set, tuple):
        args = get_args(annotation)
        return f"{ts_type(args[0])}[]" if args else "unknown[]"
    if origin is dict:
        args = get_args(annotation)
        key = "string" if not args else ("string" if args[0] in (str,) or (isinstance(args[0], type) and issubclass(args[0], Enum)) else "string")
        value = ts_type(args[1]) if len(args) > 1 else "unknown"
        return f"Record<{key}, {value}>"

    if isinstance(annotation, type):
        if issubclass(annotation, Enum):
            return annotation.__name__
        if issubclass(annotation, BaseModel):
            return annotation.__name__
        if annotation is Decimal:
            return "string"
        if annotation in (datetime, date):
            return "string"
        if annotation is bool:
            return "boolean"
        if annotation in (int, float):
            return "number"
        if annotation is str:
            return "string"
    return "unknown"


def generate_typescript() -> str:
    out: list[str] = [
        "// GENERATED by `python -m packages.contracts.export`. Do not edit by hand.",
        "//",
        "// These types come from the Pydantic models in packages/contracts/models.py,",
        "// which are also what CALL-E receives as `recipient_result_schema`. One source of",
        "// truth, three consumers.",
        "//",
        "// Money and dates are `string` on the wire on purpose -- a Decimal serialized as a",
        "// JSON float is exactly the drift we are avoiding. Format them, never sum them.",
        "",
    ]

    for name, enum_cls in sorted(ENUMS.items()):
        members = " | ".join(f'"{m.value}"' for m in enum_cls)
        out.append(f"export type {name} = {members}")
    out.append("")

    for name, model in sorted(MODELS.items()):
        doc = (model.__doc__ or "").strip().split("\n")[0]
        if doc:
            out.append(f"/** {doc} */")
        out.append(f"export interface {name} {{")
        for field_name, field in model.model_fields.items():
            optional = not field.is_required()
            rendered = ts_type(field.annotation)
            description = (field.description or "").strip()
            if description:
                out.append(f"  /** {description} */")
            out.append(f"  {field_name}{'?' if optional else ''}: {rendered}")
        out.append("}")
        out.append("")

    return "\n".join(out)


# ---------------------------------------------------------------------------


def export_schemas() -> Path:
    SCHEMA_DIR.mkdir(parents=True, exist_ok=True)
    bundle = {name: model.model_json_schema() for name, model in sorted(MODELS.items())}
    path = SCHEMA_DIR / "schema.json"
    path.write_text(json.dumps(bundle, indent=2) + "\n", encoding="utf-8")

    # The one CALL-E needs, on its own, so Slice C can point at a single file.
    claim_path = SCHEMA_DIR / "claim.schema.json"
    claim_path.write_text(
        json.dumps(contract_models.Claim.model_json_schema(), indent=2) + "\n", encoding="utf-8"
    )
    return path


def export_typescript() -> Path:
    UI_LIB.mkdir(parents=True, exist_ok=True)
    path = UI_LIB / "contracts.ts"
    path.write_text(generate_typescript(), encoding="utf-8")
    return path


def export_fixtures() -> list[Path]:
    """A recorded case, not a mock.

    These come from the same endpoints the cockpit would call live, so the
    offline demo and the live one are the same code path with a different source.
    """
    from fastapi.testclient import TestClient

    from backend.api.main import app

    fixtures_dir = UI_LIB / "fixtures"
    fixtures_dir.mkdir(parents=True, exist_ok=True)
    client = TestClient(app)

    written: list[Path] = []

    def dump(name: str, payload: Any) -> None:
        path = fixtures_dir / name
        path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
        written.append(path)

    dump("shortages.json", client.get("/dashboard/shortages").json())
    dump("profile.json", client.get("/profile").json())
    dump("cases.json", client.get("/cases").json())

    for case_id in client.get("/cases").json():
        cid = case_id["case_id"]
        dump(f"{cid}.json", client.get(f"/cases/{cid}").json())
        dump(f"{cid}.events.json", client.get(f"/cases/{cid}/events").json())
        artifacts = client.get(f"/cases/{cid}/artifacts").json()["artifacts"]
        bodies = {
            a["name"]: client.get(f"/cases/{cid}/artifacts/{a['name']}").json()["body"]
            for a in artifacts
            if a["is_markdown"]
        }
        dump(f"{cid}.artifacts.json", bodies)

    return written


def main() -> None:
    schema = export_schemas()
    types = export_typescript()
    fixtures = export_fixtures()
    print(f"schema     {schema.relative_to(REPO_ROOT)}  ({len(MODELS)} models, {len(ENUMS)} enums)")
    print(f"typescript {types.relative_to(REPO_ROOT)}")
    for path in fixtures:
        print(f"fixture    {path.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
"""CALL-E result -> Quote. This function is never allowed to raise.

A missing, partial, or garbled call result becomes a valid Quote with
fields defaulted to unknown and confidence 0.0. A later phase distrusts
any claim below a confidence threshold, so a broken call flows naturally
into "we couldn't verify this one" rather than halting the run.
"""

from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any

from packages.contracts.models import (
    Currency,
    ExpediteOption,
    PriceBreak,
    Quote,
    TranscriptTurn,
)


def _decimal(value: Any) -> Decimal | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _int(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return int(value)
    except (ValueError, TypeError):
        return None


def _currency(value: Any) -> Currency:
    try:
        return Currency(str(value).upper())
    except (ValueError, AttributeError):
        return Currency.UNKNOWN


def _price_breaks(value: Any) -> list[PriceBreak]:
    if not isinstance(value, list):
        return []
    out: list[PriceBreak] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        qty = _int(item.get("min_qty"))
        price = _decimal(item.get("unit_price"))
        if qty is not None and price is not None:
            out.append(PriceBreak(min_qty=qty, unit_price=price))
    return out


def _expedite(value: Any) -> ExpediteOption | None:
    if not isinstance(value, dict):
        return None
    days = _int(value.get("days"))
    surcharge = _decimal(value.get("surcharge"))
    if days is None or surcharge is None:
        return None
    return ExpediteOption(days=days, surcharge=surcharge)


def _transcript(value: Any) -> list[TranscriptTurn]:
    if not isinstance(value, list):
        return []
    turns: list[TranscriptTurn] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        text = item.get("text")
        speaker = item.get("speaker")
        turns.append(
            TranscriptTurn(
                offset_seconds=_int(item.get("offset_seconds")) or 0,
                speaker=speaker if isinstance(speaker, str) else "unknown",
                text=text if isinstance(text, str) else "",
            )
        )
    return turns


def _confidence(value: Any) -> float:
    # CALL-E sends {"score": 0.82, "label": "high"}, not a bare float.
    if isinstance(value, dict):
        value = value.get("score")
    try:
        return max(0.0, min(1.0, float(value)))
    except (ValueError, TypeError):
        return 0.0


def normalize_result(
    task_id: str,
    case_id: str,
    supplier_ref: str,
    payload: dict,
) -> Quote:
    result: dict = {}
    if isinstance(payload, dict) and isinstance(payload.get("structured_result"), dict):
        result = payload["structured_result"]

    certs = result.get("certs_claimed")
    if not isinstance(certs, list):
        certs = []

    # CALL-E's prose summary is often the only place a partial call's findings
    # survive, so keep it rather than dropping it on the floor.
    notes = payload.get("summary") if isinstance(payload, dict) else None
    if not isinstance(notes, str):
        notes = ""

    return Quote(
        task_id=task_id,
        case_id=case_id,
        supplier_ref=supplier_ref,
        available=bool(result.get("available", False)),
        qty_offered=_int(result.get("qty_offered")) or 0,
        unit_price=_decimal(result.get("unit_price")),
        price_breaks=_price_breaks(result.get("price_breaks")),
        currency=_currency(result.get("currency")),
        moq=_int(result.get("moq")),
        lead_time_days=_int(result.get("lead_time_days")),
        expedite_option=_expedite(result.get("expedite_option")),
        incoterm=result.get("incoterm") if isinstance(result.get("incoterm"), str) else None,
        certs_claimed=[str(c) for c in certs],
        payment_terms=(
            result.get("payment_terms")
            if isinstance(result.get("payment_terms"), str)
            else None
        ),
        notes=notes,
        summary=notes,
        transcript=_transcript(
            payload.get("transcript_turns") if isinstance(payload, dict) else None
        ),
        transcript_url=payload.get("transcript_url") if isinstance(payload, dict) else None,
        recording_url=payload.get("recording_url") if isinstance(payload, dict) else None,
        confidence=_confidence(payload.get("completion_confidence") if isinstance(payload, dict) else 0.0),
        raw=payload if isinstance(payload, dict) else {},
    )
"""Building a claim from an untrusted payload, without ever raising.

The rule from the foundation spec: a garbled, truncated or nonsense call result
becomes a claim with its fields defaulted to "unknown"/zero and confidence 0 —
not an exception. One bad call must not kill a five-supplier case mid-run, and
by the time Devin is orchestrating, an exception here costs a whole session.

So this module reads defensively, field by field, and discards anything it
cannot understand into `raw` where a human can still go and look at it.
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any

from packages.contracts.enums import Answer, StockStatus
from packages.contracts.models import Currency
from packages.contracts.models import Claim, ExpediteOption, PriceBreak
from packages.contracts.money import to_decimal


def _answer(value: Any) -> Answer:
    if isinstance(value, Answer):
        return value
    if isinstance(value, bool):
        return Answer.YES if value else Answer.NO
    if isinstance(value, str):
        text = value.strip().lower()
        if text in ("yes", "y", "true", "confirmed"):
            return Answer.YES
        if text in ("no", "n", "false", "denied"):
            return Answer.NO
    return Answer.UNKNOWN


def _stock_status(value: Any) -> StockStatus:
    if isinstance(value, StockStatus):
        return value
    if isinstance(value, str):
        try:
            return StockStatus(value.strip().lower())
        except ValueError:
            pass
    return StockStatus.UNCLEAR


def _int(value: Any, default: int | None = None) -> int | None:
    try:
        if value is None or isinstance(value, bool):
            return default
        return int(float(str(value).strip().replace(",", "")))
    except (TypeError, ValueError):
        return default


def _money(value: Any):
    try:
        if value is None or isinstance(value, bool):
            return None
        parsed = to_decimal(value)
    except (TypeError, ValueError, ArithmeticError):
        return None
    # NaN and Infinity are parseable Decimals and poisonous money: they would
    # propagate silently through the cost model. Treat them as "not quoted".
    if not parsed.is_finite():
        return None
    return parsed


def _currency(value: Any) -> Currency:
    """An unrecognised currency is `unknown`, not a crash and not a guessed EUR."""
    if isinstance(value, Currency):
        return value
    if isinstance(value, str):
        try:
            return Currency(value.strip().upper())
        except ValueError:
            return Currency.UNKNOWN
    return Currency.UNKNOWN


def _confidence(value: Any) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return 0.0
    if number != number:  # NaN
        return 0.0
    return max(0.0, min(1.0, number))


def _price_breaks(value: Any) -> list[PriceBreak]:
    if not isinstance(value, list):
        return []
    breaks: list[PriceBreak] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        qty = _int(entry.get("min_qty"))
        price = _money(entry.get("unit_price"))
        if qty is None or qty < 1 or price is None:
            continue
        breaks.append(PriceBreak(min_qty=qty, unit_price=price))
    return sorted(breaks, key=lambda b: b.min_qty)


def _expedite(value: Any) -> ExpediteOption | None:
    if not isinstance(value, dict):
        return None
    days = _int(value.get("days"))
    surcharge = _money(value.get("surcharge"))
    if days is None or surcharge is None:
        return None
    return ExpediteOption(days=days, surcharge=surcharge)


def _strings(value: Any) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(item) for item in value if item is not None]
    return []


def _text(value: Any, default: str = "") -> str:
    return value.strip() if isinstance(value, str) else default


def claim_from_result(
    result: Any,
    *,
    task_id: str,
    case_id: str,
    supplier_ref: str,
    call_id: str | None = None,
    round_: int = 1,
) -> Claim:
    """Build a `Claim` from whatever a call returned. Never raises.

    `result` is treated as entirely untrusted: `None`, a string, a list, or a
    dict with wrong types in every field all produce a valid confidence-0 claim
    rather than an error.
    """
    payload: dict[str, Any] = result if isinstance(result, dict) else {}
    unparsed = {} if isinstance(result, dict) else {"unparsed_result": repr(result)[:2000]}

    return Claim(
        task_id=task_id,
        case_id=case_id,
        supplier_ref=supplier_ref,
        round=round_,
        call_id=call_id,
        qty_offered=_int(payload.get("qty_offered"), 0) or 0,
        earliest_ready_text=_text(payload.get("earliest_ready_text")),
        stock_status=_stock_status(payload.get("stock_status")),
        lead_time_days=_int(payload.get("lead_time_days")),
        price_quoted=_answer(payload.get("price_quoted")),
        unit_price=_money(payload.get("unit_price")),
        price_breaks=_price_breaks(payload.get("price_breaks")),
        moq=_int(payload.get("moq")),
        currency=_currency(payload.get("currency")),
        expedite_option=_expedite(payload.get("expedite_option")),
        incoterm=_text(payload.get("incoterm")) or None,
        payment_terms=_text(payload.get("payment_terms")) or None,
        part_number_confirmed=_answer(payload.get("part_number_confirmed")),
        certification_current=_answer(payload.get("certification_current")),
        certs_claimed=_strings(payload.get("certs_claimed")),
        notes=_text(payload.get("notes")),
        transcript_url=_text(payload.get("transcript_url")) or None,
        recording_url=_text(payload.get("recording_url")) or None,
        confidence=_confidence(payload.get("confidence")),
        evidence=_strings(payload.get("evidence")),
        raw={**payload, **unparsed},
        received_at=datetime.now(timezone.utc),
    )
